import unittest
from dashboard import Dashboard

class DashboardTests(unittest.TestCase):
    def test_cache_and_expiry(self):
        reads=[]
        def read(hour):
            reads.append(hour)
            return 14
        dash=Dashboard(read,'Europe/Bratislava',7200)
        for now in (0,1,7200):
            self.assertEqual(dash.total('2025-10-20T00:00:00+00:00',now),14)
        self.assertEqual(len(reads),2)
    def test_distinct_hours(self):
        data={'2025-10-20T00:00:00+00:00':14,'2025-10-20T01:00:00+00:00':93}
        dash=Dashboard(data.__getitem__,'Europe/Bratislava')
        self.assertEqual([dash.total(h,i) for i,h in enumerate(data)],[14,93])

